const { initializeStateCollections, SqliteStateCollection } = await import(process.cwd()+"/src/lib/state/sqliteStateStore.ts");
const { buildPipeline, isStoredPipeline } = await import(process.cwd()+"/src/lib/pipelines/store.ts");
const { readHistoryProjection, historyAttemptCounts } = await import(process.cwd()+"/src/lib/state/historyProjection.ts");
import { Database } from "bun:sqlite";
import path from "node:path";
const now="2026-10-21T12:00:00.000Z";
const role={roleId:"builder",engine:"codex",model:null,effort:null,access:"read-write",promptScaffold:"fixture"};
const rows=Array.from({length:48},(_,i)=>{
 const p=buildPipeline({id:`pipeline_${String(i).padStart(3,"0")}`,project:"fixture",task:"fixture",repoDir:"/repo",srcPath:null,srcConversationId:null,now,stages:[{id:"build",kind:"run",prompt:"x".repeat(4096),role:{roleId:"builder"},effectiveRole:role,next:null}] } as never);
 p.state="running";p.runs[0]!.attempts=Array.from({length:12},(_,n)=>({n:n+1,state:n===11?"running":"passed",effectiveRole:role,launchId:null,sessionId:null,flowId:null,input:null,activatedBy:null,output:null,conversationId:`conversation_${i}_${n}`,agentPath:`fixture-${i}-${n}.jsonl`,paneId:null,startedAt:now,completedAt:n===11?null:now,verdict:n===11?null:{status:"pass"},error:"x".repeat(4096)})) as never;
 return p;
});
if(!rows.every(isStoredPipeline)) throw new Error("invalid benchmark pipeline");
const spec={collection:"pipelines",schemaVersion:1,busyMessage:"busy",key:(p:typeof rows[number])=>p.id,decode:(r:unknown)=>r as typeof rows[number],clone:structuredClone};
const filename=path.join(process.env.LLV_STATE_DIR!,"bench.sqlite");
initializeStateCollections(filename,[{...spec,migrationId:"bench",loadRecords:()=>rows}]);const store=new SqliteStateCollection(filename,spec);
const samples=[];
for(let cycle=0;cycle<8;cycle++){
 const start=performance.now();
 for(const row of rows){row.runs[0]!.attempts[11]!.state=cycle%2?"running":"pending";store.boundedPatch(1,tx=>tx.put(row));}
 const written=performance.now();
 const count=await readHistoryProjection(db=>historyAttemptCounts(db,"fixture",Date.parse(now)),{filename});
 if(!count || count.builder!==576)throw new Error(JSON.stringify(count));
 const end=performance.now();if(cycle)samples.push({write:written-start,history:end-written,total:end-start});
}
console.log(JSON.stringify({sqlite:new Database(":memory:").query("SELECT sqlite_version() AS version").get(),rows:48,attempts:12,payloadBytes:JSON.stringify(rows[0]).length,samples}));
